}

@Test
void isEnabled() {
    Tracer.ENABLED = false;
    Tracer tracer = Tracer.start("doesn't matter");
    assertFalse(tracer.isEnabled());
    Tracer.ENABLED = true;
    assertTrue(tracer.isEnabled());
    Tracer.ENABLED = false;
    assertFalse(tracer.isEnabled());
}

