        Struct fieldsStruct = new Struct(fieldSchema).put("running", false).put("numLargeBoxes", 765);
        Struct struct = new Struct(schema).put("fields", fieldsStruct).put(Constants.TIMESTAMP_CONFIG, System.currentTimeMillis()).put("expires", 0L);
